"""Compiled checks for C2-S2. GENERATED by solution/recompute.py. DO NOT HAND-EDIT.

Every check below runs against delivered bytes and references no unmeasured quantity, except
chain_end_state_accuracy_ramp, which raises ConstantUnmeasured while tests/constants.json carries
nulls. The graded quantity is Chain end-state accuracy over 1200 private executable tool-call episodes, priced against harness-measured wall clock through the two-axis composite instruction.md publishes verbatim: r_det = quality_fraction * (0.55 + 0.45 * speed_fraction). An episode counts only when the emitted call chain executes to completion in the pinned sandbox, the backend end-state digest equals gold's exactly, and every order-dependent pair appears in gold's relative order. There is no per-call partial credit.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SUBMISSION = '/submission/c2s2.json'
CHECKS = []


class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "C2-S2: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; "
            "the Phase 2 measurement wave writes these and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "submitted_artifact"), "values": kw}

@check(id="chain_end_state_accuracy_ramp", weight=10, knockout=True, kind="process")
def test_chain_end_state_accuracy_ramp():
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    # require_measured is the FIRST statement, before any read of the submission or the run
    # record. Reading the chain manifest first lets a missing-file error mask the unmeasured
    # signal: the verifier then reports gradeable=true with r_det=0.0, which collapses "not
    # yet measurable" into "the agent scored zero". Those are different claims.
    accuracy = measure()
    span = c["knee"] - c["floor"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (accuracy - c["floor"]) / span))
    reach = T - BASE_ACCURACY
    quality = 0.0 if reach <= 0 else max(0.0, min(1.0, (accuracy - BASE_ACCURACY) / reach))
    return accuracy >= c["dichotomizing_threshold"], evidence(
        target="episode_ledger", chain_end_state_accuracy=accuracy,
        quality_fraction=quality, s_outcome=s)

