@check(id="consumed_digest_resolves_to_an_earlier_producing_stage", weight=5, knockout=True, kind="process")
def test_consumed_digest_resolves_to_an_earlier_producing_stage():
    try:
        records = invocations()
    except Exception as exc:
        return False, evidence(target="chain_manifest", reason="manifest_malformed",
                               error=str(exc))
    producers = artifact_producers()
    if producers is None:
        return False, evidence(target="chain_manifest",
                               reason="artifact_producers_unpublished")
    # latest[artifact name] = (digest, producing stage) as the chain runs forward. Closure is
    # per ARTIFACT NAME and against the MOST RECENT digest under it, not against an acyclic
    # predecessor: the GRPO cycle re-enters rollout, score and update many times and update
    # legitimately re-produces merged_weights for the next rollout. What is never legitimate
    # is eating a digest a later invocation has already superseded -- which is exactly what
    # the pinned score stage does when it is pointed at a previous iteration's rollout file,
    # accepting it and exiting 0.
    latest, broken = {}, []
    for index, record in enumerate(records):
        stage = record.get("stage")
        for entry in (record.get("consumed") or []):
            if not isinstance(entry, dict):
                broken.append({"invocation": index, "why": "consumed_entry_malformed"})
                continue
            name, digest = entry.get("artifact"), entry.get("sha256")
            if name not in producers:
                broken.append({"invocation": index, "stage": stage, "artifact": name,
                               "why": "artifact_not_declared"})
                continue
            if name not in latest:
                broken.append({"invocation": index, "stage": stage, "artifact": name,
                               "why": "no_earlier_producer"})
                continue
            produced_digest, producer = latest[name]
            if producer not in producers[name]:
                broken.append({"invocation": index, "stage": stage, "artifact": name,
                               "producer": producer,
                               "why": "producer_not_declared_for_this_artifact"})
            elif digest != produced_digest:
                broken.append({"invocation": index, "stage": stage, "artifact": name,
                               "why": "superseded_digest_consumed"})
        for entry in (record.get("produced") or []):
            if isinstance(entry, dict) and is_digest(entry.get("sha256")):
                latest[entry.get("artifact")] = (entry["sha256"], stage)
    return (not broken), evidence(target="chain_manifest", offending=broken[:6],
                                  artifacts_produced=len(latest),
                                  reason=None if not broken else "chain_closure_broken")

