@check(id="end_state_digest_equality_with_no_per_call_credit", weight=5, knockout=True, kind="process")
def test_end_state_digest_equality_with_no_per_call_credit():
    book = ledger()
    if book is None:
        return False, evidence(target="episode_ledger", reason="episode_ledger_unrecorded")
    record = run_record()
    basis = record.get("counting_basis")
    per_call = record.get("per_call_accuracy")
    faults = []
    if basis != COUNTING_BASIS:
        faults.append({"why": "counting_basis_is_not_end_state_equality", "declared": basis})
    if not isinstance(per_call, (int, float)) or isinstance(per_call, bool):
        faults.append({"why": "per_call_accuracy_not_recorded_separately"})
    for name in sorted(STRATUM_TOTALS):
        row = book.get(name) if isinstance(book.get(name), dict) else {}
        counted = row.get("counted")
        equal = row.get("end_state_equal")
        ran = row.get("executed_to_completion")
        violations = row.get("order_violations")
        if not all(isinstance(v, int) and not isinstance(v, bool)
                   for v in (counted, equal, ran, violations)):
            faults.append({"stratum": name, "why": "accounting_incomplete"})
            continue
        if not (ran <= STRATUM_TOTALS[name] and equal <= ran):
            faults.append({"stratum": name, "why": "more_equal_than_executed"})
        if counted != equal - violations:
            faults.append({"stratum": name, "why": "counted_ignores_order_dependent_pairs",
                           "counted": counted, "end_state_equal": equal,
                           "order_violations": violations})
    ok = not faults
    return ok, evidence(target="episode_ledger", counting_basis=basis,
                        per_call_accuracy=per_call, offending=faults[:6],
                        reason=None if ok else "per_call_credit_leaked_into_the_numerator")

@check(id="every_invocation_names_consumed_and_produced_digests", weight=5, knockout=True, kind="process")
def test_every_invocation_names_consumed_and_produced_digests():
    try:
        records = invocations()
    except Exception as exc:
        return False, evidence(target="chain_manifest", reason="manifest_malformed",
                               error=str(exc))
    faults = []
    for index, record in enumerate(records):
        absent = [key for key in INVOCATION_KEYS if key not in record]
        if absent:
            faults.append({"invocation": index, "absent_keys": absent})
            continue
        if not isinstance(record.get("bindings"), dict):
            faults.append({"invocation": index, "why": "bindings_not_a_map"})
        for side in ("consumed", "produced"):
            entries = record.get(side)
            if not isinstance(entries, list):
                faults.append({"invocation": index, "side": side, "why": "not_a_list"})
                continue
            for entry in entries:
                if not isinstance(entry, dict) or "artifact" not in entry \
                        or not is_digest(entry.get("sha256")):
                    faults.append({"invocation": index, "side": side,
                                   "why": "not_an_artifact_digest_pair"})
        if not (record.get("produced") or []):
            faults.append({"invocation": index, "side": "produced",
                           "why": "produced_nothing"})
        if not (record.get("consumed") or []) and record.get("stage") != "seed":
            faults.append({"invocation": index, "side": "consumed",
                           "why": "only_seed_may_consume_nothing"})
    return (not faults), evidence(target="chain_manifest", invocations=len(records),
                                  offending=faults[:6],
                                  reason=None if not faults else "manifest_malformed")

