@check(id="invoked_stage_digest_equals_the_pinned_tool_digest", weight=5, knockout=True, kind="process")
def test_invoked_stage_digest_equals_the_pinned_tool_digest():
    try:
        declared = section("stage_digests")
        records = invocations()
    except Exception as exc:
        return False, evidence(target="stage_tree", reason="manifest_malformed",
                               error=str(exc))
    pinned = run_record().get("pinned_stage_digests")
    if not isinstance(pinned, dict) or not pinned:
        return False, evidence(target="stage_tree", reason="pinned_stage_digests_unrecorded")
    absent = [stage for stage in STAGES if stage not in declared]
    added = sorted(set(map(str, declared)) - set(STAGES))
    drifted = sorted(stage for stage in STAGES
                     if stage in declared and stage in pinned
                     and declared[stage] != pinned[stage])
    unpinned = [stage for stage in STAGES if stage not in pinned]
    shimmed = sorted({record.get("stage") for record in records
                      if record.get("stage") in pinned
                      and record.get("stage_digest") != pinned[record.get("stage")]})
    ok = not (absent or added or drifted or unpinned or shimmed)
    return ok, evidence(target="stage_tree", tools_absent=absent, tools_added=added,
                        digests_drifted=drifted, tools_unpinned=unpinned,
                        invoked_off_pin=shimmed,
                        reason=None if ok else "stage_tree_written")

