@check(id="realized_sequence_linearizes_the_declared_partial_order", weight=5, knockout=True, kind="process")
def test_realized_sequence_linearizes_the_declared_partial_order():
    try:
        records = invocations()
    except Exception as exc:
        return False, evidence(target="chain_manifest", reason="manifest_malformed",
                               error=str(exc))
    edges = declared_edges()
    if edges is None:
        return False, evidence(target="chain_manifest",
                               reason="declared_partial_order_unpublished")
    first = {}
    for index, record in enumerate(records):
        first.setdefault(record.get("stage"), index)
    absent = [stage for stage in STAGES if stage not in first]
    # First occurrence, not every occurrence: the GRPO cycle re-enters rollout, score and
    # update many times, and a linearization of a partial order constrains where a stage may
    # START, not how often it may repeat once its predecessors have run.
    violated = [{"edge": "%s->%s" % (a, b), "first_seen": [first[a], first[b]]}
                for a, b in edges if a in first and b in first and first[a] > first[b]]
    ok = (not absent) and (not violated)
    return ok, evidence(target="chain_manifest", stages_absent=absent, violated=violated,
                        realized=[r.get("stage") for r in records][:12],
                        reason=None if ok else "stage_order_not_a_linearization")

@check(id="replay_on_a_fresh_epoch_reproduces_the_end_state_digests", weight=3, knockout=False, kind="process")
def test_replay_on_a_fresh_epoch_reproduces_the_end_state_digests():
    record = run_record()
    replay = record.get("sandbox_replay")
    if not isinstance(replay, dict) or not replay:
        return False, evidence(target="run_record", reason="sandbox_replay_unrecorded")
    first = replay.get("first_pass_digest")
    second = replay.get("second_pass_digest")
    if not (is_digest(first) and is_digest(second)):
        return False, evidence(target="run_record", reason="replay_digests_unreadable",
                               first=first, second=second)
    stable = first == second
    # A FRESHLY seeded epoch, not the one the graded run held. Replaying inside the graded
    # epoch re-reads a world the run already mutated and would agree with itself for the
    # wrong reason.
    graded_epoch = replay.get("graded_epoch_id")
    replay_epoch = replay.get("epoch_id")
    fresh = bool(replay_epoch) and replay_epoch != graded_epoch
    covered = replay.get("episodes_replayed")
    complete = covered == EPISODE_TOTAL
    ok = stable and fresh and complete
    return ok, evidence(target="run_record", first_pass_digest=first,
                        second_pass_digest=second, replay_epoch=replay_epoch,
                        graded_epoch=graded_epoch, episodes_replayed=covered,
                        reason=None if ok else
                        ("end_state_digest_flapped" if not stable else
                         "replay_epoch_not_fresh" if not fresh
                         else "replay_incomplete"))

@check(id="score_epoch_equals_the_rollout_and_seed_epoch", weight=5, knockout=True, kind="process")
def test_score_epoch_equals_the_rollout_and_seed_epoch():
    try:
        records = invocations()
    except Exception as exc:
        return False, evidence(target="chain_manifest", reason="manifest_malformed",
                               error=str(exc))
    seeds = [r for r in records if r.get("stage") == "seed"]
    if not seeds:
        return False, evidence(target="chain_manifest", reason="epoch_unbound",
                               why="no_seed_invocation_to_bind_against")
    seed_epoch = seeds[0].get("epoch_id")
    origin = {}
    for record in records:
        for entry in (record.get("produced") or []):
            if isinstance(entry, dict) and is_digest(entry.get("sha256")):
                origin[entry["sha256"]] = record
    unbound = []
    scored = 0
    for index, record in enumerate(records):
        if record.get("stage") != "score":
            continue
        scored += 1
        if record.get("epoch_id") != seed_epoch:
            unbound.append({"invocation": index, "why": "score_epoch_differs_from_seed"})
        sources = [origin.get((e or {}).get("sha256")) for e in (record.get("consumed") or [])
                   if isinstance(e, dict)]
        rollouts = [s for s in sources if s is not None and s.get("stage") == "rollout"]
        if not rollouts:
            unbound.append({"invocation": index, "why": "score_consumed_no_rollout_artifact"})
        for source in rollouts:
            if source.get("epoch_id") != record.get("epoch_id"):
                unbound.append({"invocation": index,
                                "why": "rollout_epoch_differs_from_score_epoch"})
    ok = scored > 0 and not unbound
    return ok, evidence(target="chain_manifest", seed_epoch=seed_epoch,
                        score_invocations=scored, offending=unbound[:6],
                        reason=None if ok else "epoch_unbound")

@check(id="strata_counts_partition_the_1200_private_episodes", weight=3, knockout=False, kind="process")
def test_strata_counts_partition_the_1200_private_episodes():
    book = ledger()
    if book is None:
        return False, evidence(target="episode_ledger", reason="episode_ledger_unrecorded")
    absent = [name for name in sorted(STRATUM_TOTALS) if name not in book]
    if absent:
        return False, evidence(target="episode_ledger", strata_absent=absent,
                               reason="episode_ledger_incomplete")
    wrong_total, out_of_range = [], []
    summed = 0
    for name, expected in sorted(STRATUM_TOTALS.items()):
        row = book[name] if isinstance(book[name], dict) else {}
        total, counted = row.get("total"), row.get("counted")
        if total != expected:
            wrong_total.append({"stratum": name, "declared": total, "published": expected})
        if not isinstance(counted, int) or counted < 0 or counted > expected:
            out_of_range.append({"stratum": name, "counted": counted})
        summed += expected
    partitions = summed == EPISODE_TOTAL
    ok = partitions and not wrong_total and not out_of_range
    return ok, evidence(target="episode_ledger", summed_totals=summed,
                        published_total=EPISODE_TOTAL, wrong_totals=wrong_total,
                        counts_out_of_range=out_of_range,
                        reason=None if ok else "strata_do_not_partition_the_split")

@check(id="timed_window_is_host_measured_not_self_reported", weight=3, knockout=False, kind="process")
def test_timed_window_is_host_measured_not_self_reported():
    record = run_record()
    elapsed = record.get("harness_measured_elapsed_s")
    if not isinstance(elapsed, (int, float)) or isinstance(elapsed, bool):
        return False, evidence(target="run_record", reason="harness_elapsed_unrecorded")
    elapsed = float(elapsed)
    ceiling = BUDGET_SECONDS + BUDGET_GRACE_SECONDS
    within = elapsed <= ceiling
    try:
        records = invocations()
    except Exception as exc:
        return False, evidence(target="run_record", reason="manifest_malformed",
                               error=str(exc))
    outside = []
    for index, invocation in enumerate(records):
        start, end = invocation.get("started_s"), invocation.get("ended_s")
        if not all(isinstance(v, (int, float)) and not isinstance(v, bool)
                   for v in (start, end)):
            outside.append({"invocation": index, "why": "offsets_unrecorded"})
        elif start < 0 or end > elapsed or start > end:
            outside.append({"invocation": index, "window": [start, end]})
    ok = within and not outside
    return ok, evidence(target="run_record", harness_measured_elapsed_s=elapsed,
                        ceiling_with_grace=ceiling, offending=outside[:6],
                        reason=None if ok else
                        ("budget_exceeded" if not within
                         else "invocation_outside_the_timed_window"))

@check(id="twelve_ablation_rewards_lie_inside_a_007_band", weight=3, knockout=False, kind="process")
def test_twelve_ablation_rewards_lie_inside_a_007_band():
    table = run_record().get("link_ablation_accuracy")
    if not isinstance(table, dict) or not table:
        return False, evidence(target="run_record", reason="link_ablation_unrecorded")
    try:
        measured = [float(table[name]) for name in BOUND_ARGUMENTS if name in table]
    except Exception as exc:
        return False, evidence(target="run_record", reason="link_ablation_unparseable",
                               error=str(exc))
    complete = len(measured) == len(BOUND_ARGUMENTS)
    width = (max(measured) - min(measured)) if measured else None
    ok = complete and width is not None and width <= ABLATION_BAND
    return ok, evidence(target="run_record", ablations=len(measured), band_width=width,
                        band_ceiling=ABLATION_BAND,
                        reason=None if ok
                        else "ablation_band_localizes_the_broken_link")

@check(id="twelve_interface_arguments_bound_inside_published_domains", weight=5, knockout=True, kind="process")
def test_twelve_interface_arguments_bound_inside_published_domains():
    try:
        bindings = section("argument_bindings")
    except Exception as exc:
        return False, evidence(target="argument_bindings", reason="manifest_malformed",
                               error=str(exc))
    domains = run_record().get("argument_domains")
    if not isinstance(domains, dict) or not domains:
        return False, evidence(target="argument_bindings",
                               reason="argument_domains_unpublished")
    unbound = [name for name in BOUND_ARGUMENTS if name not in bindings]
    undeclared = sorted(set(map(str, bindings)) - set(BOUND_ARGUMENTS))
    no_domain = [name for name in BOUND_ARGUMENTS if not isinstance(domains.get(name), list)]
    outside = [name for name in BOUND_ARGUMENTS
               if name in bindings and isinstance(domains.get(name), list)
               and bindings[name] not in domains[name]]
    sizes = [len(domains[name]) for name in BOUND_ARGUMENTS
             if isinstance(domains.get(name), list)]
    published = sizes == list(ARGUMENT_DOMAIN_SIZES)
    ok = not (unbound or undeclared or no_domain or outside) and published
    return ok, evidence(target="argument_bindings", unbound=unbound, undeclared=undeclared,
                        domainless=no_domain, out_of_domain=outside,
                        domain_sizes=sizes, combinations=product(sizes),
                        reason=None if ok else "manifest_malformed")

@check(id="two_axis_composite_uses_the_published_weights_verbatim", weight=3, knockout=False, kind="process")
def test_two_axis_composite_uses_the_published_weights_verbatim():
    try:
        declared = section("composite_declaration")
    except Exception as exc:
        return False, evidence(reason="manifest_malformed", error=str(exc))
    try:
        quality_weight = float(declared["quality_weight"])
        speed_weight = float(declared["speed_weight"])
        quality_fraction = float(declared["quality_fraction"])
        speed_fraction = float(declared["speed_fraction"])
        composite = float(declared["composite"])
    except Exception as exc:
        return False, evidence(reason="composite_declaration_unparseable", error=str(exc))
    weights_published = (quality_weight == QUALITY_WEIGHT
                         and speed_weight == SPEED_WEIGHT
                         and abs(quality_weight + speed_weight - 1.0) <= 1e-9)
    restated = quality_fraction * (quality_weight + speed_weight * speed_fraction)
    reproduces = abs(restated - composite) <= 1e-9
    ok = weights_published and reproduces
    return ok, evidence(quality_weight=quality_weight, speed_weight=speed_weight,
                        published=[QUALITY_WEIGHT, SPEED_WEIGHT],
                        declared_composite=composite, recomputed=restated,
                        reason=None if ok else "composite_reweighted_by_the_submission")

# --- the facts this slot is about ---------------------------------------------------------
# The graded object is an ORCHESTRATION over eight pinned tools the agent may compose and may
# not modify. Everything named below is a fact about that composition: which tool ran, in what
# order, under which of the twelve bound arguments, against which sandbox epoch, and what each
# invocation ate and emitted. None of it is a fact about a model.
SECTIONS = ("argument_bindings", "chain_manifest", "composite_declaration", "export_record",
            "stage_digests", "stage_seconds")

# The eight pinned stage tools, sorted. Digest-locked and read-only: the lever is the order they
# are composed in and the arguments bound across their seven link boundaries, never their bytes.
STAGES = ("export", "merge", "render", "rollout", "score", "seed", "sft", "update")

INVOCATION_KEYS = ("bindings", "consumed", "epoch_id", "produced", "stage", "stage_digest")

# The twelve declared interface arguments, in the order instruction.md publishes their domain
# sizes. Each one is bound across a link boundary, and each mis-binding alone sinks the run
# below T1 while every stage still exits 0.
BOUND_ARGUMENTS = ("--mask-convention", "--generation-prompt", "--pad-side", "--epoch-binding",
                   "--score-input", "--export-form", "--embed-resize",
                   "--tokenizer-fingerprint", "--advantage-baseline", "--reference-dtype",
                   "--merge-before-rollout", "--decoy-downweight")
ARGUMENT_DOMAIN_SIZES = (2, 3, 2, 3, 3, 2, 3, 3, 3, 3, 2, 3)

# Fallback partial order, used only when the run record publishes none. Seven edges over eight
# stages; at least forty distinct linearizations satisfy it and every one runs to a clean exit.
DECLARED_EDGES = (("render", "sft"), ("sft", "merge"), ("merge", "rollout"), ("seed", "rollout"),
                  ("rollout", "score"), ("score", "update"), ("update", "export"))

# Fallback artifact-producer map, used only when the run record publishes none. merged_weights
# has two declared producers because the loop re-produces it; nothing else does.
DECLARED_ARTIFACT_PRODUCERS = {
    "world_state": frozenset(("seed",)),
    "render_spec": frozenset(("render",)),
    "rendered_episodes": frozenset(("render",)),
    "adapter": frozenset(("sft",)),
    "merged_weights": frozenset(("merge", "update")),
    "rollout_samples": frozenset(("rollout",)),
    "episode_rewards": frozenset(("score",)),
    "export_bundle": frozenset(("export",)),
}

T = 0.42                       # the family's highest target, at family_position 3
T1 = 0.34                      # the lowest target; each single-link ablation must fall below it
BASE_ACCURACY = 0.08           # measured vendored-instruct-base end-state accuracy
ABLATION_BAND = 0.07           # the width the twelve ablation accuracies must fit inside
HAYSTACK_MARGIN = 0.10
TRANSFER_MARGIN = 0.16
STRATUM_CAP = 0.60
QUALITY_WEIGHT = 0.55
SPEED_WEIGHT = 0.45
BUDGET_SECONDS = 3600.0
BUDGET_GRACE_SECONDS = 300.0
STRATUM_TOTALS = {"haystack": 200, "main": 700, "transfer": 300}
EPISODE_TOTAL = 1200
COUNTING_BASIS = "backend_end_state_digest_equality_with_order_dependent_pairs"
PRIVATE_EPISODE_TREE = "/private/episodes"
ADMISSIBILITY_REASON_CODES = (
    "boundary_violation", "budget_exceeded", "chain_closure_broken", "empty_submission",
    "epoch_unbound", "export_form_rejected", "export_unloadable", "grading_tree_written",
    "heldout_mutated", "manifest_absent", "manifest_malformed", "stage_tree_written",
    "unsanctioned_checkpoint")


def load_submission():
    """The orchestration's account of itself: what it composed, how it bound the interface,
    which tool bytes it invoked, what it exported, how it restated the published composite and
    where its seconds went. Not a model and not a training log."""
    with open(SUBMISSION) as handle:
        doc = json.load(handle)
    if not isinstance(doc, dict):
        raise ValueError("the deliverable must be a JSON object")
    return doc


def section(name):
    doc = load_submission()
    if name not in doc:
        raise KeyError("the submission carries no %s section" % name)
    return doc[name]


def invocations():
    """The realized invocation sequence, in the order the manifest lists it.

    List order IS the claim about execution order. Nothing here re-sorts by a timestamp the
    submission supplies, because sorting would repair the very ordering the closure and the
    linearization checks exist to measure.
    """
    chain = section("chain_manifest")
    if not isinstance(chain, list) or not chain:
        raise ValueError("chain_manifest must be a non-empty list of invocation records")
    for record in chain:
        if not isinstance(record, dict):
            raise ValueError("every chain_manifest entry must be an invocation record")
    return chain


def is_digest(value):
    return (isinstance(value, str) and len(value) == 64
            and all(c in "0123456789abcdef" for c in value))


def binding_at(record, argument):
    """The value one invocation was called with for one declared argument.

    Read per invocation rather than from the top-level bindings map: the whole point of the
    render-to-rollout and rollout-to-update links is that one argument can carry two different
    values at two invocations, with both stages exiting 0.
    """
    bindings = record.get("bindings")
    return bindings.get(argument) if isinstance(bindings, dict) else None


def product(sizes):
    total = 1
    for size in sizes:
        total *= size
    return total


def declared_edges():
    """The declared partial order, read from the run record; the constant is the fallback."""
    published = run_record().get("declared_partial_order")
    if published is None:
        return DECLARED_EDGES
    if not isinstance(published, list):
        return None
    edges = []
    for edge in published:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            return None
        edges.append((str(edge[0]), str(edge[1])))
    return tuple(edges)


def artifact_producers():
    """Which stage is declared to produce each named artifact.

    Published in instruction.md and echoed in the run record. It is a per-artifact map rather
    than a per-stage one because the GRPO cycle re-produces merged_weights at update and hands
    it back to rollout: the chain is not acyclic and closure cannot be stated as "an acyclic
    predecessor produced this". What closure DOES state is that the digest eaten is the most
    recent one emitted under that name by a stage entitled to emit it.
    """
    published = run_record().get("artifact_producers")
    if published is None:
        return DECLARED_ARTIFACT_PRODUCERS
    if not isinstance(published, dict) or not published:
        return None
    out = {}
    for name, stages in published.items():
        if not isinstance(stages, (list, tuple)):
            return None
        out[str(name)] = frozenset(str(stage) for stage in stages)
    return out


def run_record():
    """The record the graded run and the harness produced together.

    The wall clock, the pinned tool digests, the declared partial order, the argument domains,
    the episode ledger, the twelve single-link ablations, the mount manifest and the grader's
    reason-code vocabulary all live here. Read from here rather than from a scan taken
    afterwards, which cannot separate what happened inside the timed window from what happened
    before it, and never from a number the submission reports about itself.
    """
    path = os.path.join(HERE, "..", "run_record.json")
    if not os.path.exists(path):
        return {}
    with open(path) as handle:
        return json.load(handle)


def ledger():
    book = run_record().get("episode_ledger")
    return book if isinstance(book, dict) and book else None


def stratum_accuracy(book, name):
    row = book.get(name) if isinstance(book, dict) else None
    if not isinstance(row, dict):
        return None
    counted = row.get("counted")
    total = STRATUM_TOTALS.get(name)
    if not isinstance(counted, int) or isinstance(counted, bool) or not total:
        return None
    return counted / float(total)


def harvest(node, words, numbers):
    """Every string and every number anywhere in the submission, object keys included."""
    if isinstance(node, dict):
        for key, value in node.items():
            words.add(str(key).lower())
            harvest(value, words, numbers)
    elif isinstance(node, list):
        for value in node:
            harvest(value, words, numbers)
    elif isinstance(node, bool):
        pass
    elif isinstance(node, (int, float)):
        numbers.add(float(node))
    elif isinstance(node, str):
        words.add(node.lower())
    return words, numbers


def measure():
    """acc = summed counted episodes over the summed 1200, from the verifier's own ledger.

    The denominator is rebuilt by summing the three published stratum totals rather than read
    from any total the record states beside them, and the numerator counts only episodes whose
    backend end-state digest equalled gold's. No number the submission reports enters either.
    """
    book = ledger()
    if book is None:
        raise ConstantUnmeasured("the verifier has written no private episode ledger")
    counted, total = 0, 0
    for name, published in STRATUM_TOTALS.items():
        row = book.get(name)
        if not isinstance(row, dict) or not isinstance(row.get("counted"), int):
            raise ConstantUnmeasured("stratum %s carries no counted episodes" % name)
        counted += row["counted"]
        total += published
    if total != EPISODE_TOTAL:
        raise ConstantUnmeasured("the strata do not partition the 1200 private episodes")
    return counted / float(total)
